(function () {
  var loadWordpacks = GetWordpacks.run()
    .then(function () {
      var packs = Array.isArray(GetWordpacks.data) ? GetWordpacks.data : [];
      if (!packs.length) {
        storeValue('selectedWordpack', null);
        return;
      }

      var current = appsmith.store.selectedWordpack;
      var currentId = current && current.id;
      if (currentId) {
        var found = packs.find(function (p) { return String(p.id) === String(currentId); }) || null;
        storeValue('selectedWordpack', found);
      }
    })
    .catch(function (e) {
      showAlert('Wordpacks load failed: ' + ((e && e.message) ? e.message : e), 'error');
    });

  var loadHints = GetPowerups.run()
    .then(function () {
      var hints = Array.isArray(GetPowerups.data) ? GetPowerups.data : [];
      if (!hints.length) {
        storeValue('selectedHintType', null);
        return;
      }

      var current = appsmith.store.selectedHintType;
      var currentId = current && current.id;
      if (currentId) {
        var found = hints.find(function (h) { return String(h.id) === String(currentId); }) || null;
        storeValue('selectedHintType', found);
      }
    })
    .catch(function (e) {
      showAlert('Hint types load failed: ' + ((e && e.message) ? e.message : e), 'error');
    });

  var loadLogs = Promise.all([
    GetGameSessions.run().catch(function () {}),
    GetGuessLog.run().catch(function () {}),
    GetApiLogs.run().catch(function () {}),
  ]);

  return Promise.all([loadWordpacks, loadHints, loadLogs]);
})()
}}

