children.onClick:
{{
(function () {
  var playerName = (PlayerNameInput.text || '').trim();
  if (!playerName) {
    showAlert('Enter a player name first.', 'warning');
    return;
  }

  storeValue('playerName', playerName);
  storeValue('gameActive', false);
  storeValue('status', 'Starting new game...');
  storeValue('guesses', []);
  storeValue('hints', []);
  storeValue('wordLength', '-');
  storeValue('sessionId', null);
  storeValue('backendSource', null);
  storeValue('wordpackInUse', null);

  try {
    resetWidget('GuessInput');
  } catch (e) {}

  var selectedPack = appsmith.store.selectedWordpack || null;
  var packWords = selectedPack && selectedPack.words;
  var desiredLength = Math.max(3, parseInt(LookupWordInput.text, 10) || 8);

  var afterStart = function (res, overrideMessage) {
    if (!res) {
      throw new Error('Start response was empty');
    }
    storeValue('gameActive', true);
    storeValue('wordLength', res.word_length);
    storeValue('sessionId', res.session_id);
    storeValue('backendSource', res.word_source);
    storeValue('wordpackInUse', res.wordpack_name);
    var msg = overrideMessage || res.message;
    storeValue('status', msg + ' (Session #' + res.session_id + ')');
    return GetLeaderboard.run();
  };

  var startLocal = function (msg) {
    return StartGame.run().then(function (res) {
      return afterStart(res, msg);
    });
  };

  if (Array.isArray(packWords) && packWords.length) {
    var matches = packWords.filter(function (w) { return (w || '').length === desiredLength; });
    if (!matches.length) {
      showAlert('Selected wordpack has no words of length ' + desiredLength + '; starting external word instead.', 'warning');
    } else {
      return StartGameFromWordpack.run()
        .then(function (res) {
          return afterStart(res);
        })
        .catch(function () {
          showAlert('Wordpack start failed, starting local word.', 'warning');
          return startLocal('Wordpack unavailable; started local word instead.');
        });
    }
  }

  return ServerlessLookup.run()
    .then(function () {
      return LogServerlessLookup.run().catch(function () {});
    })
    .then(function () {
      return StartGameExternal.run().then(function (res) {
        return afterStart(res);
      });
    })
    .catch(function () {
      return startLocal('External API unavailable; started local word instead.');
    })
    .catch(function (err) {
      storeValue('gameActive', false);
      showAlert('Start failed: ' + ((err && err.message) ? err.message : err), 'error');
    });
})()
}}

{{
(function () {
  if (!appsmith.store.gameActive) {
    showAlert('Start a new game first.', 'warning');
    return;
  }
  var guess = (GuessInput.text || '').trim();
  if (!guess) {
    showAlert('Enter a guess first.', 'warning');
    return;
  }

  return MakeGuess.run()
    .then(function (res) {
      storeValue('guesses', (res && res.all_guesses) ? res.all_guesses : []);
