      } else {
        var similarity = (res && typeof res.similarity === 'number') ? res.similarity.toFixed(4) : '-';
        storeValue('status', 'Similarity: ' + similarity + ' - keep guessing.');
      }
      return GetLeaderboard.run();
    })
    .catch(function (e) {
      showAlert('Guess failed: ' + ((e && e.message) ? e.message : e), 'error');
    });
})()
}}

